mapper.insert:
insert into support_access_grants(
    grant_id, actor_user_id, actor_username, incident_id, reason, session_digest,
    issued_at, expires_at, revoked_at, revoke_reason, trace_id
) values (
    #{grantId}, #{actorUserId}, #{actorUsername}, #{incidentId}, #{reason}, #{sessionDigest},
    #{issuedAt}, #{expiresAt}, #{revokedAt}, #{revokeReason}, #{traceId}
)

mapper.update:
update support_access_grants
set revoked_at = #{revokedAt}, revoke_reason = #{reason}
where grant_id = #{grantId} and revoked_at is null

mapper.insert:
insert into support_access_audit_events(
    event_id, grant_id, actor_user_id, actor_username, target_user_id, target_username,
    incident_id, reason, action, resource_type, resource_id, path_digest, outcome,
    error_code, trace_id, ip_address, user_agent_digest, occurred_at
) values (
    #{eventId}, #{grantId}, #{actorUserId}, #{actorUsername}, #{targetUserId}, #{targetUsername},
    #{incidentId}, #{reason}, #{action}, #{resourceType}, #{resourceId}, #{pathDigest}, #{outcome},
    #{errorCode}, #{traceId}, #{ipAddress}, #{userAgentDigest}, #{occurredAt}
)

mapper.sql:
where 1 = 1
and actor_user_id = #{actorUserId}
and target_user_id = #{targetUserId}
and incident_id = #{incidentId}
and outcome = #{outcome}

mapper.delete:
delete from support_access_grants g
where g.expires_at < #{cutoff}
  and not exists (
      select 1 from support_access_audit_events e where e.grant_id = g.grant_id
  )
